/**
 * Candidate landing sites near the lunar south pole, loaded from the real
 * NASA-derived data generated by `pipeline/` (see ../../CLAUDE.md sec. 6-7).
 *
 * Coordinates, elevation and horizon come from NASA LOLA; Sun/Earth tracks
 * come from JPL Horizons. Slope is NOT part of the real contract (the pipeline
 * does not compute it yet) - kept as a constant purely for the procedural
 * surface renderer in `surface-world.ts`, not used in scoring.
 */
import type { EphemerisFile, GlobalFile, HorizonFile, HorizonSource, Site, SitesFile, TerrainInfo, Track } from '@touchdown/core';
import { sphericalHorizon, trackFromFile } from '@touchdown/core';
import { loadTerrainPatch, type TerrainPatch } from './terrain';

const DEFAULT_SLOPE_DEG = 6.5;

export interface SiteInput {
  id: string;
  name: string;
  lat: number;
  lon: number;
  elevationKm: number;
  slopeDeg: number;
  note?: string;
  track: Track;
  horizon: HorizonFile;
  hasTerrain: boolean;
  horizonSource: HorizonSource;
  ephemerisSource: string;
  /** Real LOLA heightmap, only set when hasTerrain is true. */
  terrain?: TerrainPatch;
}

export interface MissionData {
  /** Planned landing time (UTC). */
  landingDate: Date;
  sites: SiteInput[];
  /** Moon-fixed sub-solar/sub-earth series, for the orbit phase (see global-track.ts). */
  global: GlobalFile;
}

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`fetch ${url} failed: ${res.status}`);
  return res.json() as Promise<T>;
}

/**
 * Loads the real catalog + per-site ephemeris/horizon generated by the
 * pipeline (`web/public/data/`). onProgress(0..1, message) drives the launch
 * animation.
 */
export async function loadMissionData(onProgress: (p: number, msg: string) => void): Promise<MissionData> {
  onProgress(0, 'Cargando catálogo de sitios · NASA LOLA + JPL Horizons');
  const [catalog, global, terrains] = await Promise.all([
    fetchJson<SitesFile>('/data/sites.json'),
    fetchJson<GlobalFile>('/data/global.json'),
    fetchJson<Record<string, TerrainInfo>>('/data/terrains.json'),
  ]);

  const sites: SiteInput[] = [];
  for (let i = 0; i < catalog.sites.length; i++) {
    const s = catalog.sites[i]!;
    onProgress((i + 0.5) / catalog.sites.length, `Efemérides y horizonte · ${s.name}`);
    const [ephemeris, horizon] = await Promise.all([
      fetchJson<EphemerisFile>(`/data/ephemeris/${s.id}.json`),
      fetchJson<HorizonFile>(`/data/horizons/${s.id}.json`),
    ]);
    let terrain: TerrainPatch | undefined;
    if (s.has_terrain) {
      onProgress((i + 0.8) / catalog.sites.length, `Terreno LOLA (heightmap) · ${s.name}`);
      const info = terrains[s.id];
      if (!info) throw new Error(`sitio ${s.id} marca has_terrain pero falta en terrains.json`);
      terrain = await loadTerrainPatch(info);
    }
    sites.push({
      id: s.id,
      name: s.name,
      lat: s.lat,
      lon: s.lon,
      elevationKm: s.elevation_m / 1000,
      slopeDeg: DEFAULT_SLOPE_DEG,
      note: s.notes,
      track: trackFromFile(ephemeris),
      horizon,
      hasTerrain: s.has_terrain,
      horizonSource: s.horizon_source,
      ephemerisSource: s.ephemeris_source,
      terrain,
    });
  }

  onProgress(1, 'Datos listos');
  // Landing date must fall inside the precomputed ephemeris range (see sites.json.ephemeris_range).
  return { landingDate: new Date(Date.UTC(2027, 0, 10, 0, 0)), sites, global };
}

export type { Site };

/**
 * Synthetic single-site mission for dev-only entry points that skip the real
 * async load (the `?phase=orbit|pov|...` shortcut in app.ts). NEVER used in
 * the normal launch -> loadMissionData flow. Flat/constant values, not NASA
 * data - DO NOT present this as a real scenario.
 */
export function devFallbackMission(): MissionData {
  const startMs = Date.UTC(2026, 10, 1);
  const stepMs = 3_600_000;
  const count = 24 * 400; // ~400 days, hourly
  const flat = (v: number) => Array.from({ length: count }, () => v);
  const track: Track = {
    siteId: 'dev-fallback', source: 'DEV_FALLBACK_NOT_REAL', startMs, stepMs, count,
    sunAz: flat(90), sunEl: flat(3), earthAz: flat(10), earthEl: flat(5),
  };
  const global: GlobalFile = {
    source: 'DEV_FALLBACK_NOT_REAL',
    start: new Date(startMs).toISOString(),
    step_minutes: 60,
    count,
    sub_earth_lon: flat(0), sub_earth_lat: flat(0), sub_solar_lon: flat(0), sub_solar_lat: flat(0),
    earth_range_km: flat(384_400),
  };
  const site: SiteInput = {
    id: 'dev-fallback', name: 'Sitio de desarrollo (sin datos reales)',
    lat: -85, lon: 0, elevationKm: 3, slopeDeg: DEFAULT_SLOPE_DEG,
    note: 'Fallback de desarrollo — no es un sitio real, solo para ?phase=... sin pasar por loadMissionData.',
    track, horizon: sphericalHorizon('dev-fallback'), hasTerrain: false,
    horizonSource: 'spherical', ephemerisSource: 'DEV_FALLBACK_NOT_REAL',
  };
  return { landingDate: new Date(startMs + 30 * 86_400_000), sites: [site], global };
}
